// Central feature flags and store configuration (docs/RELEASE_ANDROID.md).
//
// The flags come from the build (`virtual:tens-features`, generated by viteConfigFactory.js's
// resolveFeatureFlags): ADS_ENABLED / IAP_ENABLED are true only in a Capacitor build with
// VITE_TENS_ADS_ENABLED / VITE_TENS_IAP_ENABLED=true, and CLOUD_SAVE_ENABLED only when a Firebase
// web config is supplied. With a flag off, that feature's code is never bundled, so the GitHub
// Pages web build can never load ad or purchase code.
export { ADS_ENABLED, CLOUD_SAVE_ENABLED, IAP_ENABLED, IS_NATIVE_BUILD } from 'virtual:tens-features'

export const FIREBASE_CONFIG = {
  apiKey: import.meta.env.VITE_FIREBASE_API_KEY,
  authDomain: import.meta.env.VITE_FIREBASE_AUTH_DOMAIN,
  projectId: import.meta.env.VITE_FIREBASE_PROJECT_ID,
  appId: import.meta.env.VITE_FIREBASE_APP_ID,
}

// Google's published sample ids (https://developers.google.com/admob/android/test-ads,
// .../ios/test-ads). Always used in dev builds; production builds use the real ids from env and
// fall back to these (with test mode on) while the placeholders are unset.
export const ADMOB_TEST_REWARDED_IDS = {
  android: 'ca-app-pub-3940256099942544/5224354917',
  ios: 'ca-app-pub-3940256099942544/1712485313',
}

const realRewardedIds = {
  android: import.meta.env.VITE_ADMOB_REWARDED_ID_ANDROID,
  ios: import.meta.env.VITE_ADMOB_REWARDED_ID_IOS,
}

export const getRewardedAdUnit = (platform, { dev = import.meta.env.DEV, ids = realRewardedIds } = {}) => {
  const real = ids[platform]
  if (dev || !real) return { adId: ADMOB_TEST_REWARDED_IDS[platform], isTesting: true }
  return { adId: real, isTesting: false }
}

export const REVENUECAT_API_KEYS = {
  android: import.meta.env.VITE_REVENUECAT_API_KEY_ANDROID,
  ios: import.meta.env.VITE_REVENUECAT_API_KEY_IOS,
}

/** RevenueCat entitlement unlocked by the remove-ads purchase. */
export const REMOVE_ADS_ENTITLEMENT = 'remove_ads'

/** Store product ids — must match Play Console / App Store Connect / RevenueCat. */
export const IAP_PRODUCTS = {
  removeAds: { id: import.meta.env.VITE_IAP_REMOVE_ADS_ID || 'tens_remove_ads', type: 'non_consumable' },
  supportTip: { id: import.meta.env.VITE_IAP_SUPPORT_TIP_ID || 'tens_support_tip', type: 'consumable' },
}

// Hosted on the GitHub Pages site (public/privacy.html, public/terms.html). Absolute so the native
// apps open the live copy in the system browser.
export const SITE_URL = 'https://mohanpednekar.github.io/tens/'
export const PRIVACY_POLICY_URL = `${SITE_URL}privacy.html`
export const TERMS_URL = `${SITE_URL}terms.html`
